{
  "name": "束线狭缝",
  "name_en": "Beamline Slits",
  "manufacturer": "",
  "description": "用于X射线束线中的机械狭缝装置，通过调节水平和垂直方向的开口宽度与中心位置来限定束斑尺寸、调整束流通过区域，并可在需要时关闭或完全阻挡光束。该类设备常用于束流整形、对准、光路管理和实验站前的束流控制。",
  "description_en": "A mechanical slit device used on X-ray beamlines to define the beam aperture by adjusting the horizontal and vertical opening widths and center positions. It is used to shape the beam, control the transmitted region, align the beam path, and close or fully block the beam when needed for lightpath control and experiment setup.",
  "tag_hints": [
    "x-ray beam shaping",
    "beam aperture control",
    "slit width and center adjustment",
    "beam blocking",
    "lightpath control",
    "beamline alignment"
  ],
  "actions": [
    {
      "action_name": "auto-block",
      "description": "使狭缝叶片重叠以完全阻挡光束。",
      "description_en": "Overlap the slit blades to fully block the beam."
    },
    {
      "action_name": "auto-calc_lightpath_state",
      "description": "根据当前狭缝开口计算光路是通过还是被阻挡。",
      "description_en": "Calculate whether the current slit aperture allows beam transmission or blocks the lightpath."
    },
    {
      "action_name": "auto-close",
      "description": "关闭狭缝，使开口收至接近零。",
      "description_en": "Close the slits so the aperture is reduced to nearly zero."
    },
    {
      "action_name": "auto-open",
      "description": "打开狭缝至预设开口，使光束通过。",
      "description_en": "Open the slits to a predefined aperture to allow beam transmission."
    },
    {
      "action_name": "auto-format_status_info",
      "description": "整理并输出当前狭缝状态信息。",
      "description_en": "Format and report the current slit status information."
    },
    {
      "action_name": "auto-move",
      "description": "移动狭缝的中心位置或开口尺寸到目标值。",
      "description_en": "Move the slit center position or aperture size to a target value."
    },
    {
      "action_name": "auto-current_aperture",
      "description": "获取当前狭缝开口尺寸。",
      "description_en": "Get the current slit aperture size."
    },
    {
      "action_name": "auto-position",
      "description": "获取当前狭缝位置。",
      "description_en": "Get the current slit position."
    },
    {
      "action_name": "auto-remove",
      "description": "将狭缝打开到不遮挡光束的状态。",
      "description_en": "Open or retract the slits to a state that does not obstruct the beam."
    },
    {
      "action_name": "auto-set",
      "description": "设定狭缝的目标位置或目标开口。",
      "description_en": "Set the target slit position or target aperture."
    },
    {
      "action_name": "auto-stage",
      "description": "使狭缝进入准备运行状态。",
      "description_en": "Prepare the slit system for operation."
    },
    {
      "action_name": "auto-unstage",
      "description": "使狭缝退出准备运行状态。",
      "description_en": "Return the slit system from its prepared operating state."
    },
    {
      "action_name": "auto-subscribe",
      "description": "订阅狭缝状态或读数更新。",
      "description_en": "Subscribe to slit state or readback updates."
    },
    {
      "action_name": "auto-inserted",
      "description": "获取狭缝是否处于插入光路状态。",
      "description_en": "Get whether the slits are inserted into the beam path."
    },
    {
      "action_name": "auto-removed",
      "description": "获取狭缝是否处于移出光路或充分打开状态。",
      "description_en": "Get whether the slits are removed from the beam path or sufficiently open."
    },
    {
      "action_name": "auto-egu",
      "description": "获取狭缝运动量的工程单位。",
      "description_en": "Get the engineering units used for slit motion."
    },
    {
      "action_name": "auto-y_states",
      "description": "获取狭缝Y方向的可用状态。",
      "description_en": "Get the available Y-axis slit states."
    }
  ]
}

